#!/usr/bin/env bash
# The window switcher's rebindable keybinds, generated by the shipped
# KeybindService and checked as text.
#
#     ./tests/run-switcher-keybinds-test.sh
#
# Quickshell refuses to import QML modules from outside the directory holding
# the entry point, so the harness is staged into the repo root for the run.
# It runs on a headless compositor of its own (tests/lib/headless.sh) and skips
# without quickshell. Nothing here presses a key: a synthetic keyboard cannot
# produce the modifier RELEASE the switcher commits on, so a non-Alt release is
# only ever confirmed by a person.
set -uo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
root="$(cd "$here/.." && pwd)"
. "$here/lib/headless.sh"

if ! command -v quickshell >/dev/null 2>&1; then
    printf 'SKIP  quickshell not installed\n'
    exit 0
fi

staged="$root/.switcher-keybinds-test.qml"
cleanup() { rm -f "$staged"; headless_cleanup; }
trap cleanup EXIT INT TERM

headless_begin
headless_start || { printf 'SKIP  no compositor to host the harness\n'; exit 0; }
cp "$here/switcher-keybinds-test.qml" "$staged"

out="$(QT_LOGGING_RULES="qml=true" timeout 120 quickshell -p "$staged" 2>&1 || true)"
printf '%s\n' "$out" | grep -E "PASS|FAIL|passed=" || true

if ! grep -q "passed=" <<<"$out"; then
    printf '%s\n' "$out" | tail -20
    echo "FAIL  the harness never reached its summary"
    exit 1
fi
n="$(printf '%s\n' "$out" | grep -o 'failed=[0-9]*' | tail -1 | grep -o '[0-9]*')"
[ "$n" = "0" ]
